// run
package main

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
	"strings"
)

type person struct {
	Name string
	Age  int
}

func main() {
	m := map[string]int{"pear": 4, "apple": 1, "fig": 3, "banana": 2}

	// maps.Keys / maps.Values / maps.All return iterators in Go 1.23.
	keys := slices.Sorted(maps.Keys(m))
	fmt.Println("keys:", keys)
	vals := slices.Sorted(maps.Values(m))
	fmt.Println("values:", vals)

	var pairs []string
	for k, v := range maps.All(m) {
		pairs = append(pairs, fmt.Sprintf("%s=%d", k, v))
	}
	slices.Sort(pairs)
	fmt.Println("all:", pairs)

	// slices.Values / slices.All / slices.Collect / slices.Sorted*
	s := []string{"delta", "alpha", "charlie", "bravo"}
	fmt.Println("collect:", slices.Collect(slices.Values(s)))
	fmt.Println("sorted:", slices.Sorted(slices.Values(s)))
	fmt.Println("sortedfunc:", slices.SortedFunc(slices.Values(s),
		func(a, b string) int { return cmp.Compare(len(a), len(b)) }))

	var idx []int
	for i, v := range slices.All(s) {
		if strings.HasPrefix(v, "b") || strings.HasPrefix(v, "c") {
			idx = append(idx, i)
		}
	}
	fmt.Println("indexes:", idx)

	// Backward is 1.23 too; early exit must stop the iteration.
	var back []string
	for _, v := range slices.Backward(s) {
		back = append(back, v)
		if len(back) == 2 {
			break
		}
	}
	fmt.Println("backward first two:", back)

	// cmp.Or picks the first non-zero argument (Go 1.22).
	fmt.Println(cmp.Or(0, 0, 7, 9), cmp.Or("", "x", "y"), cmp.Or(0))

	people := []person{{"ada", 36}, {"bob", 36}, {"cy", 21}}
	slices.SortStableFunc(people, func(a, b person) int {
		return cmp.Or(cmp.Compare(a.Age, b.Age), cmp.Compare(a.Name, b.Name))
	})
	fmt.Println("sorted people:", people)

	fmt.Println("chunked:", slices.Collect(slices.Chunk([]int{1, 2, 3, 4, 5}, 2)))
}

