package main

import (
	"fmt"
	"iter"
	"maps"
	"slices"
	"unique"
)

func Count(n int) iter.Seq[int] {
	return func(yield func(int) bool) {
		for i := 0; i < n; i++ {
			if !yield(i) {
				return
			}
		}
	}
}

func Enumerate[T any](xs []T) iter.Seq2[int, T] {
	return func(yield func(int, T) bool) {
		for i, v := range xs {
			if !yield(i, v) {
				return
			}
		}
	}
}

func sumTo(n int) int {
	total := 0
	for i := range n {
		total += i
	}
	return total
}

func firstEven(seq iter.Seq[int]) (int, bool) {
	for v := range seq {
		if v%2 == 0 && v > 0 {
			return v, true
		}
	}
	return 0, false
}

func main() {
	fmt.Println(sumTo(5), sumTo(0), sumTo(1))
	var seen []int
	for v := range Count(5) {
		if v == 3 {
			break
		}
		seen = append(seen, v)
	}
	fmt.Println(seen)
	for i, s := range Enumerate([]string{"x", "y"}) {
		fmt.Println(i, s)
	}
	v, ok := firstEven(Count(6))
	fmt.Println(v, ok)
	fmt.Println(slices.Collect(Count(4)))
	fmt.Println(slices.Sorted(maps.Keys(map[string]int{"c": 3, "a": 1, "b": 2})))
	fmt.Println(slices.Sorted(maps.Values(map[string]int{"c": 3, "a": 1})))
	for i, v := range slices.All([]string{"p", "q"}) {
		fmt.Print(i, v, " ")
	}
	fmt.Println()
	for i, v := range slices.Backward([]int{7, 8, 9}) {
		fmt.Print(i, ":", v, " ")
	}
	fmt.Println()

	// unique.Make returns a comparable unique.Handle[T]
	var h0 unique.Handle[string]
	fmt.Println(h0 == unique.Handle[string]{})
	h1 := unique.Make("dup")
	h2 := unique.Make("dup")
	h3 := unique.Make("other")
	fmt.Println(h1 == h2, h1 == h3, h1.Value(), h3.Value())
	type key struct{ a, b int }
	var k1, k2 unique.Handle[key] = unique.Make(key{1, 2}), unique.Make(key{1, 2})
	fmt.Println(k1 == k2, k1.Value())
	handles := []unique.Handle[string]{h1, h2, h3}
	fmt.Println(len(handles), handles[0] == handles[1])
}

