package main

import "fmt"

type seq func(func(int) bool)
type seq2 func(func(string, int) bool)

func count(n int) seq {
	return func(yield func(int) bool) {
		for i := 0; i < n; i++ {
			fmt.Println("  produce", i)
			if !yield(i) {
				fmt.Println("  yield said stop at", i)
				return
			}
		}
		fmt.Println("  producer finished")
	}
}

func pairs() seq2 {
	return func(yield func(string, int) bool) {
		for i, s := range []string{"a", "b", "c"} {
			if !yield(s, i) {
				return
			}
		}
	}
}

func withBreak() {
	fmt.Println("break:")
	for v := range count(5) {
		fmt.Println("  got", v)
		if v == 2 {
			break
		}
	}
}

func withContinue() {
	fmt.Println("continue:")
	for v := range count(3) {
		if v == 1 {
			continue
		}
		fmt.Println("  got", v)
	}
}

func withReturn() int {
	fmt.Println("return:")
	for v := range count(5) {
		if v == 1 {
			return v * 10
		}
	}
	return -1
}

func withLabel() {
	fmt.Println("labelled break:")
outer:
	for v := range count(4) {
		for w := 0; w < 2; w++ {
			fmt.Println("  inner", v, w)
			if v == 1 && w == 1 {
				break outer
			}
			if w == 0 && v == 0 {
				continue outer
			}
		}
	}
}

func withPanic() {
	defer func() { fmt.Println("  recovered:", recover()) }()
	fmt.Println("panic:")
	for v := range count(4) {
		if v == 2 {
			panic("stop here")
		}
	}
}

func main() {
	withBreak()
	withContinue()
	fmt.Println("returned", withReturn())
	withLabel()
	withPanic()

	fmt.Println("two-value:")
	for s, i := range pairs() {
		fmt.Println("  ", s, i)
		if i == 1 {
			break
		}
	}

	// range over an int is Go 1.22; combining the two is legal
	total := 0
	for i := range 4 {
		for v := range count(i) {
			total += v
		}
	}
	fmt.Println("total", total)
}

