package main

import "fmt"

func main() {
	var fs []func() int
	for i := 0; i < 3; i++ {
		fs = append(fs, func() int { return i })
	}
	sum := 0
	for _, f := range fs {
		sum += f()
	}
	fmt.Println("three-clause sum:", sum)

	var gs []func() string
	for _, s := range []string{"a", "b", "c"} {
		gs = append(gs, func() string { return s })
	}
	out := ""
	for _, g := range gs {
		out += g()
	}
	fmt.Println("range value:", out)

	var ps []*int
	for i := 0; i < 3; i++ {
		ps = append(ps, &i)
	}
	fmt.Println("addresses distinct:", ps[0] != ps[1], *ps[0], *ps[2])

	done := make(chan int, 3)
	for i := 0; i < 3; i++ {
		go func() { done <- i }()
	}
	got := map[int]bool{}
	for k := 0; k < 3; k++ {
		_ = k
		got[<-done] = true
	}
	fmt.Println("goroutine captures:", len(got))
}

