package main

import (
	"fmt"
	"runtime"
	"sync"
)

// With a single processor, a goroutine whose loop contains no call, no channel
// operation and no allocation can only be taken off the scheduler
// asynchronously. Everything here must still finish.
func main() {
	prev := runtime.GOMAXPROCS(1)
	defer runtime.GOMAXPROCS(prev)

	stop := false
	var wg sync.WaitGroup
	progressed := 0

	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n := 0
			// no call, no channel operation, no allocation, and no atomic:
			// only asynchronous preemption can take this goroutine off the
			// single processor this program is allowed
			for !stop {
				n++
			}
			progressed += n % 2
		}()
	}

	done := make(chan int, 3)
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func(k int) {
			defer wg.Done()
			total := 0
			for j := 0; j < 50000; j++ {
				total += j * k
			}
			done <- total % 97
		}(i)
	}
	for i := 0; i < 3; i++ {
		<-done
	}
	fmt.Println("workers finished while spinners ran")

	runtime.GC()
	fmt.Println("collector completed with spinners live")

	stop = true
	wg.Wait()
	fmt.Println("spinners stopped:", progressed >= 0)
	fmt.Println("goroutines drained:", runtime.NumGoroutine() <= 2)
}

